    var items=list(order),itemHtml=items.map(function(x){x=x||{};var name=x.name||x.product_name||x.title||x.product_id||'منتج',qty=Number(x.qty||x.quantity||1)||1,price=Number(x.price||x.unit_price||0)||0;return '<tr><td style="padding:10px;border:1px solid #e5e7eb">'+esc(name)+'</td><td style="padding:10px;border:1px solid #e5e7eb;text-align:center">'+qty+'</td><td style="padding:10px;border:1px solid #e5e7eb;text-align:center">'+esc(money(price,s))+'</td></tr>'}).join('');
