    var s=settings(),vals={set_customerBrevoApiKey:s.customerBrevoApiKey||'',set_customerSenderName:s.customerSenderName||'',set_customerSenderEmail:s.customerSenderEmail||''};Object.keys(vals).forEach(function(id){var x=el(id);if(x&&document.activeElement!==x)x.value=vals[id]});['Order','Confirm','Processing','Shipped','Delivered','Cancelled','Payment','Refund'].forEach(function(x){var box=el('set_customerNotify'+x);if(box)box.checked=s['customerNotify'+x]!==false})
