  window.saveCustomerNotificationSettingsV18=async function(){var key=txt(el('set_customerBrevoApiKey')&&el('set_customerBrevoApiKey').value).trim(),from=txt(el('set_customerSenderEmail')&&el('set_customerSenderEmail').value).trim(),name=txt(el('set_customerSenderName')&&el('set_customerSenderName').value).trim()||'Beauty Life';if(!key)return o('اكتب مفتاح Brevo الخاص بالعملاء','error');if(!valid(from))return o('اكتب إيميل مرسل صحيحًا ومُعتمدًا داخل حساب Brevo الجديد','error');var data={customerBrevoEnabled:true,customerBrevoApiKey:key,customerSenderName:name,customerSenderEmail:from};['Order','Confirm','Processing','Shipped','Delivered','Cancelled','Payment','Refund'].forEach(function(x){var box=el('set_customerNotify'+x);data['customerNotify'+x]=!box||box.checked});try{await BL.saveSettings(data);saveDebug({ok:true,eventType:'customer_settings_saved',sender:from});o('تم حفظ إعدادات رسائل العملاء بشكل منفصل ✓','success')}catch(e){o(e&&e.message||'فشل حفظ إعدادات العملاء','error')}};
